actions.script:
if (!panelId) throw new Error('Choose a panel')
if (!['csv','xlsx'].includes(String(renderMode))) throw new Error('Choose CSV or XLSX')
const output=ec.service.sync().name('org.moqui.report.ReportServices.preview#Report').parameters({definitionId,panelId,
    renderMode,from:from || 'now-7d',thru:thru || 'now',variables:variables ? JSON.parse(variables) : {},filters:JSON.parse(filtersJson || '[]')}).call()
ec.web.sendJsonResponse(output)

if (!panelId) throw new Error('Choose a panel')
const output=ec.service.sync().name('org.moqui.report.ReportServices.render#Dashboard').parameters({definitionId,panelId,inspect:true,
    from:from || 'now-7d',thru:thru || 'now',variables:variables ? JSON.parse(variables) : {},filters:JSON.parse(filtersJson || '[]')}).call()
ec.web.sendJsonResponse(output)

const definition=ec.service.sync().name('org.moqui.report.ReportServices.get#Definition').parameters({definitionId}).call().definition
const variable=(definition.body.variables || []).find(variable=>variable.name===variableName)
if (!variable || variable.kind==='constant') throw new Error('Choose an editable variable')
const values=JSON.parse(variableValuesJson || '{}')
values[variableName]=variable.multi?String(variableValue || '').split(',').map(value=>value.trim()).filter(Boolean):variableValue
variableParameters={definitionId,from,thru,filtersJson}
if (panelId) variableParameters.panelId=panelId
for (const [name,value] of Object.entries(values)) variableParameters['var-'+name]=value

const definition=ec.service.sync().name('org.moqui.report.ReportServices.get#Definition').parameters({definitionId}).call().definition
const panels=definition.body && definition.body.panels
if (definition.type!=='dashboard' || !panels || !panels[panelId]) throw new Error('Choose a panel of this dashboard')
let copyId=String(panelId).slice(0,70)+'-copy'
while (panels[copyId]) copyId+='-copy'
if (copyId.length>80) throw new Error('This panel has too many copies; rename one first')
panels[copyId]=JSON.parse(JSON.stringify(panels[panelId]))
if (panels[copyId].title) panels[copyId].title=panels[copyId].title+' (copy)'
// The copy goes after the original: below the grid, or next to it in a list of panel placements.
const bottom=node=>(node && node.items || []).reduce((n,item)=>Math.max(n,item.layout?0:(Number(item.y) || 0)+(Number(item.h) || 1)),0)
const place=node=>{
    if (!node || typeof node!=='object') return false
    const items=node.items || node.children || []
    const at=items.findIndex(item=>item===panelId || item && item.panelId===panelId)
    if (at>=0) {const item=items[at];items.splice(at+1,0,typeof item==='string'?copyId:Object.assign({},item,{panelId:copyId},node.type==='grid'?{y:bottom(node)}:{}));return true}
    return items.some(item=>item && place(item.layout || (item.items?item:null)))
}
if (definition.body.layout) place(definition.body.layout)
ec.service.sync().name('org.moqui.report.ReportServices.save#Definition').parameters({definition,note:'Duplicated panel '+panelId}).call()
ec.web.sendJsonResponse({panelId:copyId})

const definition=ec.service.sync().name('org.moqui.report.ReportServices.get#Definition').parameters({definitionId}).call().definition
const panels=definition.body && definition.body.panels
if (definition.type!=='dashboard' || !panels || !panels[panelId]) throw new Error('Choose a panel of this dashboard')
delete panels[panelId]
const prune=node=>{
    if (!node || typeof node!=='object') return
    for (const key of ['items','children']) if (Array.isArray(node[key])) {
        node[key]=node[key].filter(item=>item!==panelId && !(item && item.panelId===panelId))
        for (const item of node[key]) prune(item && (item.layout || (item.items?item:null)))
    }
}
prune(definition.body.layout)
ec.service.sync().name('org.moqui.report.ReportServices.save#Definition').parameters({definition,note:'Removed panel '+panelId}).call()
ec.web.sendJsonResponse({removed:panelId})

from = from || 'now-7d'; thru = thru || 'now'
const definition = ec.service.sync().name('org.moqui.report.ReportServices.get#Definition').parameters({definitionId}).call().definition
dashboardTitle = ec.l10n.localize(definition.title || "")
dashboardDefinition = JSON.parse(JSON.stringify(definition.body || {}))
const activeFilters = [...(dashboardDefinition.filters || []),...JSON.parse(filtersJson || '[]')]
dashboardDefinition.variableValues = {}
// The time form carries the current values as one JSON parameter; a var-* parameter wins over it.
let carriedValues = {}
try { carriedValues = JSON.parse(ec.web.parameters.variableValuesJson || '{}') || {} } catch (error) { ec.logger.warn('Dashboard variableValuesJson ignored: '+String(error)) }
for (const variable of dashboardDefinition.variables || []) {
    // A label in the viewer's language when the catalog has it, as the panel titles are (report/mod.rs).
    if (variable.label) variable.label = ec.l10n.localize(variable.label)
    if (variable.kind === 'query') {
        try {
            const found = ec.service.sync().name('org.moqui.report.ReportServices.run#Query').parameters({query:{
                datasetId:variable.datasetId,from,thru,filters:activeFilters.filter(pill=>!pill.datasetId || pill.datasetId===variable.datasetId),
                aggregations:[{id:'value',type:'terms',role:'x-axis',params:{field:variable.field,size:1000}}]
            }}).call()
            const frame = (found.frames || [])[0] || {fields:[]}
            const field = frame.fields.find(field=>field.name==='value')
            variable.options = field ? field.values : []
        } catch (error) {
            ec.logger.error('Dashboard variable '+variable.name+' failed: '+String(error))
            variable.options = []
        }
    }
    const supplied = ec.web.parameters['var-'+variable.name] ?? carriedValues[variable.name]
    let value = supplied == null ? variable.default : supplied
    if (value == null) value = variable.includeAll ? '$__all' : (variable.options || [])[0]
    if (value && typeof value === 'object' && !Array.isArray(value)) value = value.value
    const values = Array.isArray(value) ? value : (value == null || value === '' ? [] : [value])
    dashboardDefinition.variableValues[variable.name] = variable.multi ? values : values[0]
    if (variable.field && variable.kind !== 'groupBy' && values.length && !values.includes('$__all')) {
        activeFilters.push({datasetId:variable.datasetId,query:{field:{name:variable.field,op:'in',values}}})
    }
}
const rendered = ec.service.sync().name('org.moqui.report.ReportServices.render#Dashboard').parameters({definitionId,
    variables:dashboardDefinition.variableValues,filters:JSON.parse(filtersJson || '[]'),from,thru,panelId:panelId || undefined}).call().dashboard
dashboardFrames = {};dashboardNotices = []
dashboardDefinition.filters=rendered.filters || JSON.parse(filtersJson || '[]')
dashboardDefinition.viewerId=ec.user.userId
dashboardDefinition.datasetFields={}
const datasetIds=new Set()
const collect=query=>{if(query.datasetId)datasetIds.add(query.datasetId);for(const child of query.queries || [])collect(child)}
for(const panel of Object.values(rendered.panels || {}))for(const query of panel.queries || [])collect(query)
for(const id of datasetIds){try{const dataset=ec.service.sync().name('org.moqui.report.ReportServices.get#Dataset').parameters({datasetId:id}).call().dataset;dashboardDefinition.datasetFields[id]=dataset.fields || []}catch(error){ec.logger.error('Dashboard filter fields '+id+' failed: '+String(error))}}
dashboardDefinition.layout = rendered.layout || dashboardDefinition.layout
dashboardDefinition.absoluteTime = rendered.range
// The range as asked for (now-7d, now/d), for the time picker's label; absoluteTime is what it resolved to.
dashboardDefinition.requestedTime = {from,thru}
dashboardDefinition.title = definition.title
dashboardDefinition.editable = definition.type === 'dashboard' && !definition.readOnly && definition.ownerId === ec.user.userId
dashboardDefinition.definitionId = definitionId
// The including screen's URL: the panel export, inspect and variable requests use its transitions.
dashboardDefinition.screenUrl = sri.buildUrl('.').path
dashboardDefinition.panelId = panelId || null
dashboardDefinition.kiosk = String(ec.web.parameters.kiosk || '') === 'true'
dashboardDefinition.variableValues = rendered.variableValues || dashboardDefinition.variableValues
dashboardNotices.push(...(rendered.notices || []).map(notice=>typeof notice==='string'?notice:notice.message || JSON.stringify(notice)))
dashboardVariables=(dashboardDefinition.variables || []).filter(variable=>variable.kind!=='constant').map(variable=>Object.assign({},variable,{
    currentValue:Array.isArray(dashboardDefinition.variableValues[variable.name])?dashboardDefinition.variableValues[variable.name].join(','):dashboardDefinition.variableValues[variable.name] || '',
    valueOptions:[...(variable.includeAll?[{value:'$__all',text:ec.l10n.localize('All')}]:[]),...(variable.options || []).map(item=>typeof item==='object'?{value:item.value,text:item.text || item.value}:{value:item,text:String(item)})]
}))
dashboardDefinition.panels = rendered.panels || {}
for (const [panelId,panel] of Object.entries(rendered.panels || {})) {
    dashboardFrames[panelId] = panel.frames || []
    dashboardNotices.push(...(panel.notices || []).map(notice=>panelId+': '+(typeof notice === 'string' ? notice : notice.message || JSON.stringify(notice))))
}
